import itertools

def is_triangle_free(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

def is_maximal(edges, n):
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) not in edges and (j, i) not in edges:
                new_edges = edges + [(i, j)]
                if is_triangle_free(new_edges, n):
                    return False
    return True

def find_maximal_triangle_free(n, fixed_edges):
    # Try all possible edge sets
    all_possible_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) not in fixed_edges:
                all_possible_edges.append((i, j))

    # We need to include fixed_edges
    # Let's try to build it greedily or by brute force
    # Since n=6, there are 15 possible edges. 2^15 = 32768, which is small.
    for i in range(len(all_possible_edges) + 1):
        for subset in itertools.combinations(all_possible_edges, i):
            current_edges = list(fixed_edges) + list(subset)
            if is_triangle_free(current_edges, n):
                if is_maximal(current_edges, n):
                    return current_edges
    return None

fixed_edges = [(3, 5)]
result = find_maximal_triangle_free(6, fixed_edges)
print(result)

def is_triangle_free(edges, n):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

def is_maximal(edges, n):
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) not in edges and (j, i) not in edges:
                new_edges = edges + [(i, j)]
                if is_triangle_free(new_edges, n):
                    return False
    return True

edges = [(3, 5), (0, 3), (1, 3), (2, 3), (3, 4)]
n = 6
print(f"Is triangle-free: {is_triangle_free(edges, n)}")
print(f"Is maximal: {is_maximal(edges, n)}")
